// The referee, with a direct Postgres connection instead of the REST API: the same two
// queries per move (load, then the atomic commit_room), each a short hop inside Supabase.
// `_shared/` is generated by `npm run functions:sync` from packages/engine and packages/server.
import { createClient } from '@supabase/supabase-js';
import postgres, { type JSONValue } from 'postgres';
import { handle, handsOf, parseAction, type Store, type StoredRoom } from '@tenfold/server';

const url = Deno.env.get('SUPABASE_URL');
const serviceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
const dbUrl = Deno.env.get('SUPABASE_DB_URL');
if (!url || !serviceKey || !dbUrl) throw new Error('Missing SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY or SUPABASE_DB_URL');

// Only used to verify session tokens (locally, against the project's cached signing keys).
const auth = createClient(url, serviceKey, { auth: { persistSession: false } });
// Kept open between requests while this instance stays warm. prepare: false works with
// Supabase's transaction pooler.
const sql = postgres(dbUrl, { prepare: false, max: 4, idle_timeout: 30, connect_timeout: 10 });

const cors = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-region',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
  'Access-Control-Expose-Headers': 'server-timing',
};

type Timings = Record<string, number>;

/** Room data is plain JSON; the driver's type just cannot see that through our interfaces. */
const asJson = (value: unknown) => sql.json(value as JSONValue);

const json = (body: unknown, status: number, timings: Timings) =>
  new Response(JSON.stringify(body), {
    status,
    headers: {
      ...cors,
      'Content-Type': 'application/json',
      'Server-Timing': Object.entries(timings)
        .map(([name, ms]) => `${name};dur=${ms.toFixed(1)}`)
        .join(', '),
    },
  });

const timed = async <T>(timings: Timings, name: string, run: () => Promise<T>): Promise<T> => {
  const start = performance.now();
  try {
    return await run();
  } finally {
    timings[name] = (timings[name] ?? 0) + performance.now() - start;
  }
};

const storeFor = (timings: Timings): Store => ({
  loadRoom: (key) =>
    timed(timings, 'load', async () => {
      const where = 'id' in key ? sql`r.id = ${key.id}` : sql`r.code = ${key.code}`;
      const [row] = await sql`
        select r.id, r.code, r.version, r.data, r.game,
          coalesce(
            (select json_agg(json_build_object('playerId', p.player_id, 'userId', p.user_id))
             from public.room_players p where p.room_id = r.id),
            '[]'::json
          ) as members
        from public.rooms r
        where ${where}`;
      return (row as StoredRoom | undefined) ?? null;
    }),
  createRoom: (room) =>
    timed(timings, 'save', async () => {
      const [row] = await sql`
        select public.create_room(${room.id}, ${room.code}, ${asJson(room.data)}, ${asJson(room.members)}) as ok`;
      return row?.ok === true;
    }),
  saveRoom: (room, expectedVersion) =>
    timed(timings, 'save', async () => {
      const [row] = await sql`
        select public.commit_room(
          ${room.id}, ${expectedVersion}, ${asJson(room.data)},
          ${room.game ? asJson(room.game) : null},
          ${asJson(room.members)}, ${asJson(room.game ? handsOf(room) : [])}
        ) as ok`;
      return row?.ok === true;
    }),
});

const deps = {
  random: () => crypto.getRandomValues(new Uint32Array(1))[0] / 0x100000000,
  newId: () => crypto.randomUUID(),
  now: () => Date.now(),
};

Deno.serve(async (req) => {
  const timings: Timings = {};
  if (req.method === 'OPTIONS') return new Response('ok', { headers: cors });
  if (req.method !== 'POST') return json({ ok: false, error: { code: 'bad-request' } }, 405, timings);

  const token = req.headers.get('Authorization')?.replace(/^Bearer\s+/i, '');
  const claims = token
    ? await timed(timings, 'auth', async () => (await auth.auth.getClaims(token)).data?.claims)
    : undefined;
  const userId = claims?.role === 'authenticated' ? claims.sub : undefined;
  if (!userId) return json({ ok: false, error: { code: 'unauthorized' } }, 401, timings);

  const action = parseAction(await req.json().catch(() => null));
  if (!action) return json({ ok: false, error: { code: 'bad-request' } }, 400, timings);

  try {
    return json(await handle(storeFor(timings), deps, userId, action), 200, timings);
  } catch (error) {
    console.error(error);
    return json({ ok: false, error: { code: 'server-error' } }, 500, timings);
  }
});
